import json
import sys


def summarize(values):
    if not values:
        return {"count": 0, "average": 0}
    return {"count": len(values), "average": sum(values) / len(values)}


def main():
    print(json.dumps(summarize(json.load(sys.stdin))))


if __name__ == "__main__":
    main()
